    state->parts[4]=xrtValueBytes((xbytesview){dataPrime2,sizeof(dataPrime2)});assert(state->parts[4]);
    state->parts[5]=xrtValueBytes((xbytesview){dataExponent1,sizeof(dataExponent1)});assert(state->parts[5]);
    state->parts[6]=xrtValueBytes((xbytesview){dataExponent2,sizeof(dataExponent2)});assert(state->parts[6]);
